python
def facingCardsBossReceipt(readings):
    a=readings
    out=[]
    l,r=0,len(a)-1
    while l<=r:
        out.append(a[l] if l==r else a[l]+a[r])
        l+=1
        r-=1
    return sum((i+1)*x for i,x in enumerate(out))


